def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_part = version.split('+')[0]

        # Split by '-' to separate version from pre-release
        if '-' in version_part:
            parts = version_part.split('-', 1)
            version_nums = parts[0]
            prerelease = parts[1]
        else:
            version_nums = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        major, minor, patch = map(int, version_nums.split('.'))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            prerelease_tuple = tuple(
                (0, int(x)) if x.isdigit() else (1, x)
                for x in prerelease_ids
            )
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(version):
        major, minor, patch, prerelease_tuple = parse_version(version)

        # Versions with pre-release sort before those without
        if prerelease_tuple is None:
            prerelease_sort = (1,)  # No pre-release: sorts after
        else:
            prerelease_sort = (0, prerelease_tuple)  # Has pre-release: sorts before

        return (major, minor, patch, prerelease_sort)

    return sorted(versions, key=sort_key)

